  '[{"id":"tc1","validation_type":"matching","expected_value":"Observation","description_en":"Observation","description_id":"Observasi","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Insight","description_en":"Insight","description_id":"Insight","points":25},{"id":"tc3","validation_type":"matching","expected_value":"Recommendation","description_en":"Recommendation","description_id":"Rekomendasi","points":25},{"id":"tc4","validation_type":"matching","expected_value":"The test every finding must pass","description_en":"So what","description_id":"So what","points":25}]',
