  '[{"id":"tc1","validation_type":"matching","expected_value":"Strong positive: rise together","description_en":"+0.9","description_id":"+0.9","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Strong negative: one rises as the other falls","description_en":"-0.8","description_id":"-0.8","points":25},{"id":"tc3","validation_type":"matching","expected_value":"No linear relationship","description_en":"~0","description_id":"~0","points":25},{"id":"tc4","validation_type":"matching","expected_value":"Does not prove causation","description_en":"Caveat","description_id":"Catatan","points":25}]',
